mapper.select:
select
id, resources_ip, socks5_port, socks5_user_name, socks5_password, password, is_deleted, create_user,
update_user, create_time, update_time, status
from socks5_resources

    1 = 1 and is_deleted = 0

        and id = #{id}


        and resources_ip = #{resourcesIp}


        and socks5_port = #{socks5Port}


        and socks5_user_name = #{socks5UserName}


        and socks5_password = #{socks5Password}


        and password = #{password}


        and is_deleted = #{isDeleted}


        and create_user = #{createUser}


        and update_user = #{updateUser}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and status = #{status}

